  /**
   * The four kinds of read worth delegating, and the boundary that keeps them from
   * being read as "delegate everything".
   *
   * #216, measured: the trigger ("reading you will not use again") was in both the
   * caller's prompt and this description, and delegate calls were still 55 of 17,278
   * tool calls over 185 sessions — 1 call in the 67 sessions of the two days before the
   * change. A rule whose edge a model cannot see is a rule it does not act on, so the
   * description names four shapes it can match against the tree in front of it, each
   * ending in a line, a shortlist or a yes.
   *
   * Pinned with the boundary, because the four alone read as an instruction to delegate
   * more: the file being edited and anything consulted again during the run have to stay
   * in the caller's own reading, or a run edits a file it has never read.
   *
   * And pinned with a ceiling. A tool description is resent on every turn of every run
   * that holds the tool, which is most of what a run costs, so the four examples are
   * added inside the budget the old text already spent rather than on top of it.
   */
  test("the delegate description names the four reads worth delegating, and the boundary", async () => {
    const r = await sendRequest("delegate.ts", { jsonrpc: "2.0", id: 7, method: "tools/list", params: {} }, {}, process.cwd(), ["--roster", "delegate", "--delegates-dir", ROSTER_DIR]);
    const tool = (r.result.tools as { name: string; description: string }[]).find((t) => t.name === "delegate")!;
