    expect(d, "candidates opened to narrow down").toContain("candidate files opened in turn to narrow down");
    expect(d, "grep hits read one by one").toContain("grep hits you would otherwise read one by one");
    expect(d, "a question answered in one line").toContain("a question whose answer is one line");
    // What it buys, in one sentence, and what it costs.
    expect(d, "the saving is named").toContain("What it saves is the transcript");
    // The boundary — without it the four read as "delegate more".
    expect(d, "the file being edited stays inline").toContain("The file you are about to edit");
    expect(d, "and so does anything read again this run").toContain("consult again during this run");
